class Base {
public:
    virtual void foo();
    int base_member;
};

class Derived : public Base {
public:
    void foo() override;
    int derived_member;
};

// Implementation notes:
// - Virtual functions are implemented via vtable pointers placed at the start of the object layout.
// - Constructors initialize vtable pointers and members in order, with base class constructors called first.
// - Destructors are virtual to ensure proper cleanup in inheritance hierarchies.
// - Compiler may optimize vtable placement and object layout based on optimization flags.
// - Multiple inheritance introduces multiple vtable pointers and complex memory arrangements.
